(377852, 31773, 3554, '<td valign="top">I don''t get the connection to right angles?</td>', 'I don''t get the connection to right angles?', '2003-08-06 01:07:55.000000', NULL, 1),
(377861, 31378, 3554, '<td valign="top">Nice effect. :)</td>', 'Nice effect. :)', '2003-08-06 01:11:47.000000', NULL, 1),
(377862, 31963, 10275, '<td valign="top">Great shot. You should have saved it for "Inside looking out" challenge next :-))</td>', 'Great shot. You should have saved it for "Inside looking out" challenge next :-))', '2003-08-06 01:12:42.000000', NULL, 1),
(377866, 31939, 6008, '<td valign="top">This is a good idea, and the window panes are certainly on topic, but unfortunately it looks a little blurry. You can barely tell it''s a glass window tho, and glass is very hard to photograph, so bonus points for that!</td>', 'This is a good idea, and the window panes are certainly on topic, but unfortunately it looks a little blurry. You can barely tell it''s a glass window tho, and glass is very hard to photograph, so bonus points for that!', '2003-08-06 01:15:30.000000', NULL, 1),
(377870, 32135, 3554, '<td valign="top">I thought this was pretty original.</td>', 'I thought this was pretty original.', '2003-08-06 01:18:10.000000', NULL, 1),
(377872, 32033, 6008, '<td valign="top">The idea is great and I like the composition, but the bricks on the left could do with a little more sharpness, the black spot is a little distracting, and there is quite a bit of noise in the image. Although not technically perfect, the composition and interest is good.</td>', 'The idea is great and I like the composition, but the bricks on the left could do with a little more sharpness, the black spot is a little distracting, and there is quite a bit of noise in the image. Although not technically perfect, the composition and interest is good.', '2003-08-06 01:19:02.000000', NULL, 1),
(377875, 32209, 3554, '<td valign="top">Interesting subject. I like the title.</td>', 'Interesting subject. I like the title.', '2003-08-06 01:23:31.000000', NULL, 1),
(377879, 32185, 3554, '<td valign="top">I would have liked this better if the sky were brighter and the lights darker i think. Creative idea.</td>', 'I would have liked this better if the sky were brighter and the lights darker i think. Creative idea.', '2003-08-06 01:25:45.000000', NULL, 1),
(377881, 32241, 811, '<td valign="top">Lotsa right angles, okay.  To me the picture is just a little flat -- compositionally and colorwise.  Perhaps if you could have caught a less cloudy moment, or had something  else to give it a bit of depth it would be more effective.</td>', 'Lotsa right angles, okay.  To me the picture is just a little flat -- compositionally and colorwise.  Perhaps if you could have caught a less cloudy moment, or had something  else to give it a bit of depth it would be more effective.', '2003-08-06 01:26:29.000000', NULL, 1),
(377883, 31669, 3554, '<td valign="top">Not a bad shot, but I don''t see right angles being the cornerstone of the shot.</td>', 'Not a bad shot, but I don''t see right angles being the cornerstone of the shot.', '2003-08-06 01:26:34.000000', NULL, 1),
(377885, 32191, 3554, '<td valign="top">It might have been more dramatic to have this centered and perhaps zoomed in a bit toward the top.</td>', 'It might have been more dramatic to have this centered and perhaps zoomed in a bit toward the top.', '2003-08-06 01:27:27.000000', NULL, 1),
(377887, 32072, 3554, '<td valign="top">Good challenge entry for right angles.</td>', 'Good challenge entry for right angles.', '2003-08-06 01:28:16.000000', NULL, 1),
