(378206, 31608, 10317, '<td valign="top">wonderful idea. But that shadow of the first leg on the second spoils the pic.</td>', 'wonderful idea. But that shadow of the first leg on the second spoils the pic.', '2003-08-06 05:06:02.000000', NULL, 1),
(378207, 32025, 10869, '<td valign="top">no strong right angle in your picture... it doesn''t really meet the challenge I think</td>', 'no strong right angle in your picture... it doesn''t really meet the challenge I think', '2003-08-06 05:06:45.000000', NULL, 1),
