(378210, 32023, 10317, '<td valign="top">good one - pretty natural and kind of unkempt arrangement. but a bit too over exposed.</td>', 'good one - pretty natural and kind of unkempt arrangement. but a bit too over exposed.', '2003-08-06 05:08:25.000000', NULL, 1),
(378213, 32135, 10317, '<td valign="top">excellent!</td>', 'excellent!', '2003-08-06 05:13:38.000000', NULL, 1),
(378214, 31426, 5728, '<td valign="top">For some reason this looks very familiar! I personally would have prefered a shallower DOF tho, still an interesting idea. Where is this exactly? - 6.</td>', 'For some reason this looks very familiar! I personally would have prefered a shallower DOF tho, still an interesting idea. Where is this exactly? - 6.', '2003-08-06 05:13:47.000000', NULL, 1),
(378215, 31601, 10739, '<td valign="top">did you try a higher depth of field ?</td>', 'did you try a higher depth of field ?', '2003-08-06 05:15:01.000000', NULL, 1),
