(378218, 32163, 10739, '<td valign="top">what this has to do with the challenge ?</td>', 'what this has to do with the challenge ?', '2003-08-06 05:17:56.000000', NULL, 1),
(378219, 31315, 10869, '<td valign="top">nice colors, but doesn''t really meet the challenge, no strong right angles there</td>', 'nice colors, but doesn''t really meet the challenge, no strong right angles there', '2003-08-06 05:28:17.000000', NULL, 1),
