(378235, 31997, 9758, '<td valign="top">This is a beautiful photo. Good luck...10</td>', 'This is a beautiful photo. Good luck...10', '2003-08-06 06:02:26.000000', NULL, 1),
(378236, 32227, 10869, '<td valign="top">a bit overexposed; it may have been better with focus made on the foreground</td>', 'a bit overexposed; it may have been better with focus made on the foreground', '2003-08-06 06:03:10.000000', NULL, 1),
(378237, 31773, 8987, '<td valign="top">I don''t see the right angles?</td>', 'I don''t see the right angles?', '2003-08-06 06:03:34.000000', NULL, 1),
(378238, 31939, 8987, '<td valign="top">unsharp?</td>', 'unsharp?', '2003-08-06 06:03:58.000000', NULL, 1),
(378239, 31397, 8987, '<td valign="top">Weren''t RIGHT angles supposed to be the main subject of the picture? Here the triangle is more predominant. IMHO</td>', 'Weren''t RIGHT angles supposed to be the main subject of the picture? Here the triangle is more predominant. IMHO', '2003-08-06 06:06:18.000000', NULL, 1),
(378240, 31966, 8860, '<td valign="top">A right angle with the road here would be the bike upright. I''m trying to look for other right angle references - and the only one I can think of is that this is the ''right angle'' for taking the corner at a half decent speed! Focus is a bit soft on the bike.</td>', 'A right angle with the road here would be the bike upright. I''m trying to look for other right angle references - and the only one I can think of is that this is the ''right angle'' for taking the corner at a half decent speed! Focus is a bit soft on the bike.', '2003-08-06 06:06:53.000000', NULL, 1),
(378241, 31849, 8987, '<td valign="top">as discussed in the forum the contest was clear about geometrical right angles</td>', 'as discussed in the forum the contest was clear about geometrical right angles', '2003-08-06 06:07:18.000000', NULL, 1),
(378242, 32174, 8860, '<td valign="top">I like the shot but - ''Right Angles''? I think it''s pushing the challenge brief a bit.</td>', 'I like the shot but - ''Right Angles''? I think it''s pushing the challenge brief a bit.', '2003-08-06 06:07:58.000000', NULL, 1),
(378243, 32038, 8987, '<td valign="top">the right angles aren''t the main subject?</td>', 'the right angles aren''t the main subject?', '2003-08-06 06:08:29.000000', NULL, 1),
(378244, 31570, 8860, '<td valign="top">Love the design, colours and texture in this. Also like the smaller right angles going on in the wall. A very simple, effective shot. [8]</td>', 'Love the design, colours and texture in this. Also like the smaller right angles going on in the wall. A very simple, effective shot. [8]', '2003-08-06 06:09:38.000000', NULL, 1),
(378245, 32196, 8860, '<td valign="top">Nice pattern, but it could be improved with a wider DOF. Like it though.</td>', 'Nice pattern, but it could be improved with a wider DOF. Like it though.', '2003-08-06 06:10:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(378247, 31756, 8860, '<td valign="top">Love the design in the shot. The lighting gives a very strange sensation too. Very clean and smart - if anything the slight distortion is a bit of a pain. [8]</td>', 'Love the design in the shot. The lighting gives a very strange sensation too. Very clean and smart - if anything the slight distortion is a bit of a pain. [8]', '2003-08-06 06:13:16.000000', NULL, 1),
(378250, 32029, 8860, '<td valign="top">Way off-brief - no right angles - [0]<br/> <br/>Just kidding! 97 degrees perhaps - or maybe just the angle of shot? Nice design and approach although DOF could have been deeper and tha black blacker.</td>', 'Way off-brief - no right angles - [0] Just kidding! 97 degrees perhaps - or maybe just the angle of shot? Nice design and approach although DOF could have been deeper and tha black blacker.', '2003-08-06 06:16:15.000000', NULL, 1),
(378253, 31860, 9854, '<td valign="top">Are those sprinkler heads? Great black and white!</td>', 'Are those sprinkler heads? Great black and white!', '2003-08-06 06:17:45.000000', NULL, 1),
(378255, 32053, 8860, '<td valign="top">I think this could have looked more striking with more negative space, slightly off-centre. It''s a bit too tightly cropped to the bottom. An impactful shot though. [6]</td>', 'I think this could have looked more striking with more negative space, slightly off-centre. It''s a bit too tightly cropped to the bottom. An impactful shot though. [6]', '2003-08-06 06:18:07.000000', NULL, 1),
(378256, 31937, 8860, '<td valign="top">Very intriguing shot. Love the contrast here and the sky is great, adding more interest than just the angular subject. [8]</td>', 'Very intriguing shot. Love the contrast here and the sky is great, adding more interest than just the angular subject. [8]', '2003-08-06 06:19:42.000000', NULL, 1),
(378262, 32044, 6999, '<td valign="top">Disturbingly odd - but why didn''t you shoot it from directly above: this has made the angles look wrong?</td>', 'Disturbingly odd - but why didn''t you shoot it from directly above: this has made the angles look wrong?', '2003-08-06 06:28:41.000000', NULL, 1),
(378265, 31773, 6999, '<td valign="top">You get lots of points for a disturbingly odd photo - I mean that, this is very affecting. You lose some unfortunately because I don''t see any relevance to the challenge</td>', 'You get lots of points for a disturbingly odd photo - I mean that, this is very affecting. You lose some unfortunately because I don''t see any relevance to the challenge', '2003-08-06 06:32:21.000000', NULL, 1),
(378268, 32143, 6999, '<td valign="top">This almost works for me: though i think it needs more careful lighting for such a specific study: at least some fill from the left, to show some detail on the frame; if you could have softened the light from the right too, just to reduce the harshness of those glares that might have helped also.</td>', 'This almost works for me: though i think it needs more careful lighting for such a specific study: at least some fill from the left, to show some detail on the frame; if you could have softened the light from the right too, just to reduce the harshness of those glares that might have helped also.', '2003-08-06 06:36:02.000000', NULL, 1),
(378269, 31662, 3554, '<td valign="top">I like the contrast of the gate to the grass in the background.</td>', 'I like the contrast of the gate to the grass in the background.', '2003-08-06 06:40:19.000000', NULL, 1),
(378271, 31998, 3554, '<td valign="top">I wasn''t too keen on the lighting. But I like the way you filled the frame.</td>', 'I wasn''t too keen on the lighting. But I like the way you filled the frame.', '2003-08-06 06:41:26.000000', NULL, 1),
(378276, 31405, 3554, '<td valign="top">My favorite so far.  Creative!  A bit more focus and perhaps different lighting would help mechanically, but I still really like the composition.</td>', 'My favorite so far.  Creative!  A bit more focus and perhaps different lighting would help mechanically, but I still really like the composition.', '2003-08-06 06:44:37.000000', NULL, 1),
(378277, 31661, 3554, '<td valign="top">Striking. I enjoyed this shot, especially the creative lighting.</td>', 'Striking. I enjoyed this shot, especially the creative lighting.', '2003-08-06 06:45:26.000000', NULL, 1),
(378278, 31570, 3554, '<td valign="top">The red door is striking. I like the composition.</td>', 'The red door is striking. I like the composition.', '2003-08-06 06:46:49.000000', NULL, 1),
(378279, 31940, 3554, '<td valign="top">I like the smoke.</td>', 'I like the smoke.', '2003-08-06 06:47:23.000000', NULL, 1),
(378280, 32203, 3554, '<td valign="top">I like the middle of this one, but the bottom is a bit "dirty" and overexposed. If you''d cropped off the bottom 1/4 or so I would have scored it higher. 6.</td>', 'I like the middle of this one, but the bottom is a bit "dirty" and overexposed. If you''d cropped off the bottom 1/4 or so I would have scored it higher. 6.', '2003-08-06 06:48:59.000000', NULL, 1),
(378281, 32244, 3554, '<td valign="top">I love the contrast of the red and gray. I need to learn how to do this.</td>', 'I love the contrast of the red and gray. I need to learn how to do this.', '2003-08-06 06:49:41.000000', NULL, 1),
(378282, 32218, 3554, '<td valign="top">I enjoy the composition of this one, but the lighting/contrast seems off.</td>', 'I enjoy the composition of this one, but the lighting/contrast seems off.', '2003-08-06 06:50:55.000000', NULL, 1),
(378286, 31950, 3554, '<td valign="top">Great challenge entry, especially with the reflection making right angles. The lighting and color are a bit dull though.</td>', 'Great challenge entry, especially with the reflection making right angles. The lighting and color are a bit dull though.', '2003-08-06 06:51:49.000000', NULL, 1),
(378288, 31849, 3554, '<td valign="top">I love the idea. If you could have used an indirect flash that would have helped a lot. The reflection on several of the buttons is distracting. Nice color on the flag in the foreground.</td>', 'I love the idea. If you could have used an indirect flash that would have helped a lot. The reflection on several of the buttons is distracting. Nice color on the flag in the foreground.', '2003-08-06 06:53:40.000000', NULL, 1),
(378289, 31863, 3554, '<td valign="top">I''d like to see her fill the frame more and have the background blurred. The intentional jaggies are kind of fun though.</td>', 'I''d like to see her fill the frame more and have the background blurred. The intentional jaggies are kind of fun though.', '2003-08-06 06:54:45.000000', NULL, 1),
(378290, 31380, 3554, '<td valign="top">I don''t care for the magnifying glass in the bottom left corner. If this pattern filled the frame I''d like it quite a bit more.</td>', 'I don''t care for the magnifying glass in the bottom left corner. If this pattern filled the frame I''d like it quite a bit more.', '2003-08-06 06:56:02.000000', NULL, 1),
(378292, 31770, 3554, '<td valign="top">Indoor lighting can be tough. Try playing with your ISO and aperature a bit. Or use a tripod and a slower shutter speed.  You made a good attempt to fill the frame. The picture is too soft as well.</td>', 'Indoor lighting can be tough. Try playing with your ISO and aperature a bit. Or use a tripod and a slower shutter speed.  You made a good attempt to fill the frame. The picture is too soft as well.', '2003-08-06 06:58:35.000000', NULL, 1),
(378293, 32065, 3554, '<td valign="top">This shot didn''t really communicate anything to me about right angles.</td>', 'This shot didn''t really communicate anything to me about right angles.', '2003-08-06 07:00:01.000000', NULL, 1),
(378294, 32188, 3554, '<td valign="top">I like the reflections.</td>', 'I like the reflections.', '2003-08-06 07:00:46.000000', NULL, 1),
(378300, 32247, 10565, '<td valign="top">too dark</td>', 'too dark', '2003-08-06 07:07:45.000000', NULL, 1),
(378304, 31265, 10565, '<td valign="top">A perfect 10</td>', 'A perfect 10', '2003-08-06 07:09:37.000000', NULL, 1),
(378306, 32036, 10565, '<td valign="top">The connection to the theme looks forced. If I were to see this photograph without the theme, I would say how stupid to put the pole right in middle of such  a beautiful scene.</td>', 'The connection to the theme looks forced. If I were to see this photograph without the theme, I would say how stupid to put the pole right in middle of such  a beautiful scene.', '2003-08-06 07:11:21.000000', NULL, 1),
