(378625, 31619, 6624, '<td valign="top">great title</td>', 'great title', '2003-08-06 10:52:55.000000', NULL, 1),
(378634, 31871, 5728, '<td valign="top">Well well, this face looks very familiar, as does the sepia toning :-) Good one, now go back and be nice to your wife :-)</td>', 'Well well, this face looks very familiar, as does the sepia toning :-) Good one, now go back and be nice to your wife :-)', '2003-08-06 11:05:10.000000', NULL, 1),
(378641, 31615, 5728, '<td valign="top">A wonderful photo. Not only is it full of right angles, it also brings along charachter and feeling of pensiveness and stillness.</td>', 'A wonderful photo. Not only is it full of right angles, it also brings along charachter and feeling of pensiveness and stillness.', '2003-08-06 11:17:00.000000', NULL, 1),
(378643, 31823, 5728, '<td valign="top">Fantastic shot!  Wonderful colors in the background, and those silohuettes are so crisp. The sun directly behind the figure brings it to life. Hard to tell if it is a statue or a real person.</td>', 'Fantastic shot!  Wonderful colors in the background, and those silohuettes are so crisp. The sun directly behind the figure brings it to life. Hard to tell if it is a statue or a real person.', '2003-08-06 11:19:34.000000', NULL, 1),
