INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(379456, 31841, 8970, '<td valign="top">Wish this image was taken staight on to given a receeding feeling of the supports</td>', 'Wish this image was taken staight on to given a receeding feeling of the supports', '2003-08-06 23:09:40.000000', NULL, 1),
(379457, 32248, 8298, '<td valign="top">the dark side of the building is distracting.. especially with the crop. that top left sky area seems to disturb the composition for me. a tighter crop on the left would have helped. great reflection. good angle. 5</td>', 'the dark side of the building is distracting.. especially with the crop. that top left sky area seems to disturb the composition for me. a tighter crop on the left would have helped. great reflection. good angle. 5', '2003-08-06 23:09:48.000000', NULL, 1),
(379458, 31651, 8298, '<td valign="top">very very nice. creative! nice application of the challenge theme and very textbook ''rule of thirds-ish''. focus could have been a bit tighter. lighting is good. great detail. although some of the detail of the jewellry detracts from the main subject which should be the arm and the right angles. maybe a shift in the lighting would have put more of the light on the arm and hand and less on the butt. lost points for that, but overall, excellent. compositionally superb. 9</td>', 'very very nice. creative! nice application of the challenge theme and very textbook ''rule of thirds-ish''. focus could have been a bit tighter. lighting is good. great detail. although some of the detail of the jewellry detracts from the main subject which should be the arm and the right angles. maybe a shift in the lighting would have put more of the light on the arm and hand and less on the butt. lost points for that, but overall, excellent. compositionally superb. 9', '2003-08-06 23:13:36.000000', NULL, 1),
(379464, 32030, 387, '<td valign="top">hope you didn''t get the message about vermont. something wrong. This is a nice abstract. Love the simple colors.</td>', 'hope you didn''t get the message about vermont. something wrong. This is a nice abstract. Love the simple colors.', '2003-08-06 23:21:03.000000', NULL, 1),
(379465, 32235, 9462, '<td valign="top">a border might''ve helped here...</td>', 'a border might''ve helped here...', '2003-08-06 23:22:00.000000', NULL, 1),
(379468, 31637, 8298, '<td valign="top">focus 3</td>', 'focus 3', '2003-08-06 23:23:18.000000', NULL, 1),
(379470, 31895, 8298, '<td valign="top">looks like there was too much USM or D&amp;S editing on this picture. interesting composition. good crop. 4</td>', 'looks like there was too much USM or D&S editing on this picture. interesting composition. good crop. 4', '2003-08-06 23:24:21.000000', NULL, 1),
