(380950, 32218, 10441, '<td valign="top">Remember the rule of thirds when composing or cropping a shot like this.</td>', 'Remember the rule of thirds when composing or cropping a shot like this.', '2003-08-07 16:37:11.000000', NULL, 1),
(380953, 32044, 10441, '<td valign="top">Definately fits the challenge!  Great idea, nice composure!</td>', 'Definately fits the challenge!  Great idea, nice composure!', '2003-08-07 16:38:56.000000', NULL, 1),
(381000, 32036, 8860, '<td valign="top">Although this is a lovely scene, the shot actually holds little interest beyond the sunset, and the right angle reference is quite weak. The lighting to the left of the balustrade is a bit distracting from the other natural, ambient light.</td>', 'Although this is a lovely scene, the shot actually holds little interest beyond the sunset, and the right angle reference is quite weak. The lighting to the left of the balustrade is a bit distracting from the other natural, ambient light.', '2003-08-07 17:18:04.000000', NULL, 1),
(381005, 31977, 8860, '<td valign="top">There''s something I like about this shot. It actually holds little interest really but it has good tones and ambience, despite a relatively weak right angle connection.</td>', 'There''s something I like about this shot. It actually holds little interest really but it has good tones and ambience, despite a relatively weak right angle connection.', '2003-08-07 17:20:09.000000', NULL, 1),
(381010, 32178, 8860, '<td valign="top">I find myself searching for a more interesting focal point here. Yes, there are right angles but they aren''t amazingly interesting, neither are they a key focus, or relevance, to the rest of the shot. Intriguing structure though and the ceiling area is quite strange.</td>', 'I find myself searching for a more interesting focal point here. Yes, there are right angles but they aren''t amazingly interesting, neither are they a key focus, or relevance, to the rest of the shot. Intriguing structure though and the ceiling area is quite strange.', '2003-08-07 17:22:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(381011, 32065, 8860, '<td valign="top">I''m afraid the quality and interest in this shot is just not enough. It looks very light, heavily compressed and lacks significant right-angle connections. There''s too much foreground and it''s difficult to relate the image to your title or the challenge. Sorry.</td>', 'I''m afraid the quality and interest in this shot is just not enough. It looks very light, heavily compressed and lacks significant right-angle connections. There''s too much foreground and it''s difficult to relate the image to your title or the challenge. Sorry.', '2003-08-07 17:25:21.000000', NULL, 1),
(381014, 31873, 8860, '<td valign="top">Composition is a little too centred for me (although it could have been cropped/positioned more evenly). Right angles are prominent though!</td>', 'Composition is a little too centred for me (although it could have been cropped/positioned more evenly). Right angles are prominent though!', '2003-08-07 17:27:49.000000', NULL, 1),
(381015, 32018, 10382, '<td valign="top">almost a right angle, nice exposure and composition. 7</td>', 'almost a right angle, nice exposure and composition. 7', '2003-08-07 17:28:06.000000', NULL, 1),
(381016, 31942, 8860, '<td valign="top">A more face-on viewpoint would have improved this - creating more visible, squared-up right angles. Colour is a bit washed out and the focus is soft. Border does not help.</td>', 'A more face-on viewpoint would have improved this - creating more visible, squared-up right angles. Colour is a bit washed out and the focus is soft. Border does not help.', '2003-08-07 17:29:59.000000', NULL, 1),
(381018, 31927, 8860, '<td valign="top">This house will fall down fairly soon!  Lighting is a bit flat and the interest in the shot is limited. Prominent right angles though.</td>', 'This house will fall down fairly soon!  Lighting is a bit flat and the interest in the shot is limited. Prominent right angles though.', '2003-08-07 17:31:38.000000', NULL, 1),
