(382523, 32040, 10419, '<td valign="top">A tiny bit too much of Photoshop use (hopefully legal). Blurry, overexposed. I am sorry, doesn''t do much for me.</td>', 'A tiny bit too much of Photoshop use (hopefully legal). Blurry, overexposed. I am sorry, doesn''t do much for me.', '2003-08-09 06:40:06.000000', NULL, 1),
(382525, 31770, 10419, '<td valign="top">Was this taken through a glass? It''s suffering from very low light conditions without a tripod which makes it very blurry. Also it is chopped of in a very unusual way.</td>', 'Was this taken through a glass? It''s suffering from very low light conditions without a tripod which makes it very blurry. Also it is chopped of in a very unusual way.', '2003-08-09 06:42:22.000000', NULL, 1),
