(382540, 32073, 9149, '<td valign="top">Great photo, nice composition and fits the topic. But, perhaps color is a bit dull.</td>', 'Great photo, nice composition and fits the topic. But, perhaps color is a bit dull.', '2003-08-09 07:11:40.000000', NULL, 1),
(382545, 32064, 10196, '<td valign="top">Nice combination of shapes and textures.</td>', 'Nice combination of shapes and textures.', '2003-08-09 07:47:29.000000', NULL, 1),
