(382671, 31329, 8891, '<td valign="top">The perspective here is quite fine but the composition is too centered and needs a bit of a CW rotation.</td>', 'The perspective here is quite fine but the composition is too centered and needs a bit of a CW rotation.', '2003-08-09 12:29:57.000000', NULL, 1),
(382672, 31886, 10848, '<td valign="top">This was a difficult challenge to say the least ...you have a great imagination and eye for detail....</td>', 'This was a difficult challenge to say the least ...you have a great imagination and eye for detail....', '2003-08-09 12:32:43.000000', NULL, 1),
(382673, 32202, 8891, '<td valign="top">Like the montone in the image and the great angles and texture contrasts.  The upward slope of the bricks at the top right is distracting and could easily have been done away with by cropping. down to just under the top of the lighter head stone or to the top of the strait dark stone above the door.</td>', 'Like the montone in the image and the great angles and texture contrasts.  The upward slope of the bricks at the top right is distracting and could easily have been done away with by cropping. down to just under the top of the lighter head stone or to the top of the strait dark stone above the door.', '2003-08-09 12:34:19.000000', NULL, 1),
(382674, 31661, 10848, '<td valign="top">hmmm..interesting</td>', 'hmmm..interesting', '2003-08-09 12:34:24.000000', NULL, 1),
(382675, 32209, 10848, '<td valign="top">love it!!</td>', 'love it!!', '2003-08-09 12:34:49.000000', NULL, 1),
(382676, 31384, 10848, '<td valign="top">interesting concept...the peeling paint adds dimension...I like it</td>', 'interesting concept...the peeling paint adds dimension...I like it', '2003-08-09 12:37:51.000000', NULL, 1),
(382677, 31937, 8891, '<td valign="top">Great sunset (or sunrise?) clouds with the pyramid shaped silhouette pierce through them....composition might be better, the point of the angle might be more left.  A differenct POV could have helped, shooting more or CW angle with more sky to the right of the silhouette.  Nice idea.</td>', 'Great sunset (or sunrise?) clouds with the pyramid shaped silhouette pierce through them....composition might be better, the point of the angle might be more left.  A differenct POV could have helped, shooting more or CW angle with more sky to the right of the silhouette.  Nice idea.', '2003-08-09 12:38:07.000000', NULL, 1),
(382678, 31635, 8891, '<td valign="top">The angle is great, the colors in the foreground are deadly dull. Nice touch getting another right angle on the right above the top of the wall.</td>', 'The angle is great, the colors in the foreground are deadly dull. Nice touch getting another right angle on the right above the top of the wall.', '2003-08-09 12:40:26.000000', NULL, 1),
(382680, 31765, 8891, '<td valign="top">too gray...was it shot BW? needs some oomph. Love the geometry of the building. great angles.</td>', 'too gray...was it shot BW? needs some oomph. Love the geometry of the building. great angles.', '2003-08-09 12:42:20.000000', NULL, 1),
