(383286, 31966, 2170, '<td valign="top">nice shot.  no angles.</td>', 'nice shot.  no angles.', '2003-08-10 18:26:35.000000', NULL, 1),
(383287, 32012, 2170, '<td valign="top">interesting macro</td>', 'interesting macro', '2003-08-10 18:26:51.000000', NULL, 1),
