(383292, 31274, 10402, '<td valign="top">There isn''t much here to hold a viewer''s attention. Clocks are very common, and there isn''t anything special about this view of one. The scratches and smudges are non-descript and the time 3:00:45 has no particular significance outside the challenge.</td>', 'There isn''t much here to hold a viewer''s attention. Clocks are very common, and there isn''t anything special about this view of one. The scratches and smudges are non-descript and the time 3:00:45 has no particular significance outside the challenge.', '2003-08-10 18:28:09.000000', NULL, 1),
(383293, 31397, 2170, '<td valign="top">sunspots bad.  san francisco good.</td>', 'sunspots bad.  san francisco good.', '2003-08-10 18:29:37.000000', NULL, 1),
(383294, 31961, 9893, '<td valign="top">Why didn''t you crop after rotating?</td>', 'Why didn''t you crop after rotating?', '2003-08-10 18:30:29.000000', NULL, 1),
