(383302, 32193, 2170, '<td valign="top">nice shot....but for angles?</td>', 'nice shot....but for angles?', '2003-08-10 18:38:05.000000', NULL, 1),
(383304, 31378, 5266, '<td valign="top">I like the concept, but I feel that a bit different angle - more looking down on the grating - would be a better photo.  Right now I can''t see the right angles ... I just have to assume they are there.</td>', 'I like the concept, but I feel that a bit different angle - more looking down on the grating - would be a better photo.  Right now I can''t see the right angles ... I just have to assume they are there.', '2003-08-10 18:38:42.000000', NULL, 1),
