(383313, 31663, 2170, '<td valign="top">having the doors dead-center is somewhat uninteresting....</td>', 'having the doors dead-center is somewhat uninteresting....', '2003-08-10 18:42:38.000000', NULL, 1),
(383314, 32252, 2170, '<td valign="top">the shadows in this are pretty harsh</td>', 'the shadows in this are pretty harsh', '2003-08-10 18:44:39.000000', NULL, 1),
(383315, 31265, 2170, '<td valign="top">very cool effect.</td>', 'very cool effect.', '2003-08-10 18:45:11.000000', NULL, 1),
(383317, 31651, 2170, '<td valign="top">quite dark, but i think i''d like to see outtakes of this shoot.</td>', 'quite dark, but i think i''d like to see outtakes of this shoot.', '2003-08-10 18:45:39.000000', NULL, 1),
(383318, 31770, 2170, '<td valign="top">poor focus and the lighting is too yellow.</td>', 'poor focus and the lighting is too yellow.', '2003-08-10 18:46:05.000000', NULL, 1),
(383319, 31570, 2170, '<td valign="top">nice shot.  i love the red door ... really makes it pop</td>', 'nice shot.  i love the red door ... really makes it pop', '2003-08-10 18:47:19.000000', NULL, 1),
(383320, 31484, 6477, '<td valign="top">This is a nice artwork, unfortunately I see the main subject here is curvy, and the right angles are in the ''second'' place at the frame...</td>', 'This is a nice artwork, unfortunately I see the main subject here is curvy, and the right angles are in the ''second'' place at the frame...', '2003-08-10 18:47:32.000000', NULL, 1),
(383322, 31936, 6477, '<td valign="top">great colors and reflections</td>', 'great colors and reflections', '2003-08-10 18:48:07.000000', NULL, 1),
(383324, 32010, 6477, '<td valign="top">original idea, unfortunately I see this pic kinda dark. Maybe with some bright &amp; contrast levels adjustment could be enough.</td>', 'original idea, unfortunately I see this pic kinda dark. Maybe with some bright & contrast levels adjustment could be enough.', '2003-08-10 18:50:08.000000', NULL, 1),
(383325, 32138, 2170, '<td valign="top">excellent dof</td>', 'excellent dof', '2003-08-10 18:50:48.000000', NULL, 1),
(383326, 31912, 10402, '<td valign="top">The strength of this photo comes from the girl and the object she is holding, not the fact that that object contains a couple of right angles. (The image would be just as strong if she was holding, say, a french curve.) The objects on the right side of the photo compete with the subject and should be cropped out. The glare on the girl''s chest is a bit distracting, but I like the way the lighting is arranged to put the shadow just the right place.</td>', 'The strength of this photo comes from the girl and the object she is holding, not the fact that that object contains a couple of right angles. (The image would be just as strong if she was holding, say, a french curve.) The objects on the right side of the photo compete with the subject and should be cropped out. The glare on the girl''s chest is a bit distracting, but I like the way the lighting is arranged to put the shadow just the right place.', '2003-08-10 18:51:00.000000', NULL, 1),
(383336, 32224, 6172, '<td valign="top">Maybe you should have given this a different title?  "The Right Angle of LIFE".  I gather this is on a tombstone, but that much isn''t clear.  The only clear message is the cross, which christians believe to have been not only  the death of Christ, but, more importantly, the life of all us sinners on this world.  Nice silhouette though.</td>', 'Maybe you should have given this a different title?  "The Right Angle of LIFE".  I gather this is on a tombstone, but that much isn''t clear.  The only clear message is the cross, which christians believe to have been not only  the death of Christ, but, more importantly, the life of all us sinners on this world.  Nice silhouette though.', '2003-08-10 19:06:17.000000', NULL, 1),
(383348, 32027, 6172, '<td valign="top">I think this photo could have been improved by seeing either the top or the bottom of the corner.  Also the object (person?) in the top left corner is distracting.  Otherwise a very nice photo, I like the b&amp;w, the contrast, and the sharpness of this photo.</td>', 'I think this photo could have been improved by seeing either the top or the bottom of the corner.  Also the object (person?) in the top left corner is distracting.  Otherwise a very nice photo, I like the b&w, the contrast, and the sharpness of this photo.', '2003-08-10 19:15:18.000000', NULL, 1),
(383350, 31384, 6172, '<td valign="top">Nice texture here, a little out of focus in the foreground and the glare is distracting at the top of the picture.  Nice pattern.</td>', 'Nice texture here, a little out of focus in the foreground and the glare is distracting at the top of the picture.  Nice pattern.', '2003-08-10 19:17:19.000000', NULL, 1),
(383353, 31881, 6172, '<td valign="top">Mostly curves here, I don''t see any right angles.</td>', 'Mostly curves here, I don''t see any right angles.', '2003-08-10 19:18:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(383355, 32145, 6172, '<td valign="top">Do some people really do this to their cheese?  Maybe for culinary shows?  Ok, queer concepts aside, nice colors and focus.  The lighting seems off as there is glare on the cheese in the foreground and the knife seems too dark.</td>', 'Do some people really do this to their cheese?  Maybe for culinary shows?  Ok, queer concepts aside, nice colors and focus.  The lighting seems off as there is glare on the cheese in the foreground and the knife seems too dark.', '2003-08-10 19:20:30.000000', NULL, 1),
(383357, 32230, 6172, '<td valign="top">Lots of right angles here!  I like the focus, texture and the way the puzzle seems to float in the air.  Cons - the lighting just doesn''t seem right, too "white" on the top and a little too dark on the bottom.</td>', 'Lots of right angles here!  I like the focus, texture and the way the puzzle seems to float in the air.  Cons - the lighting just doesn''t seem right, too "white" on the top and a little too dark on the bottom.', '2003-08-10 19:23:27.000000', NULL, 1),
(383359, 31863, 10402, '<td valign="top">This photo certainly meets the challenge; it''s made almost exclusively of right angles, although most are in shapes whose "blockness" is much stronger than the "right-angleness". The depth of field is nice; the background is blurred just enough to keep the designs on the boxed Lego sets from being too distracting while keeping the larger Lego logos readable. But the lighting makes the Hermione model look rather flat; the impressive 3-D structure of the model is not conveyed in the photo. And the title is too long; the fact she is made from Lego blocks is evident from the photo itself and the gratuitous use of "Right Angle" doesn''t carry much meaning outside of the challenge.</td>', 'This photo certainly meets the challenge; it''s made almost exclusively of right angles, although most are in shapes whose "blockness" is much stronger than the "right-angleness". The depth of field is nice; the background is blurred just enough to keep the designs on the boxed Lego sets from being too distracting while keeping the larger Lego logos readable. But the lighting makes the Hermione model look rather flat; the impressive 3-D structure of the model is not conveyed in the photo. And the title is too long; the fact she is made from Lego blocks is evident from the photo itself and the gratuitous use of "Right Angle" doesn''t carry much meaning outside of the challenge.', '2003-08-10 19:24:36.000000', NULL, 1),
(383374, 32153, 6172, '<td valign="top">Simple, but interesting.  Perfect lighting and focus.  Maybe this photo shouldn''t be square?</td>', 'Simple, but interesting.  Perfect lighting and focus.  Maybe this photo shouldn''t be square?', '2003-08-10 19:54:29.000000', NULL, 1),
(383383, 32251, 10402, '<td valign="top">The lines in the gate are striking, but the gate by itself isn''t very interesting. The view behind the gate isn''t very interesting either; where are the mountains from the title?</td>', 'The lines in the gate are striking, but the gate by itself isn''t very interesting. The view behind the gate isn''t very interesting either; where are the mountains from the title?', '2003-08-10 20:26:21.000000', NULL, 1),
(383386, 31866, 10402, '<td valign="top">Nice composition here, emphasizing the right angles, even the one at the top that was cut off; although not visible, it is definitely part of the photo. Unfortunately, the subject just isn''t very interesting.</td>', 'Nice composition here, emphasizing the right angles, even the one at the top that was cut off; although not visible, it is definitely part of the photo. Unfortunately, the subject just isn''t very interesting.', '2003-08-10 20:33:10.000000', NULL, 1),
(383455, 31397, 8981, '<td valign="top">I really like the lightening in this picture.  I think this could have been a really good picture for this challenge if it weren''t for the tree.  Not sure how much you could have been done there.  Good Job.</td>', 'I really like the lightening in this picture.  I think this could have been a really good picture for this challenge if it weren''t for the tree.  Not sure how much you could have been done there.  Good Job.', '2003-08-10 23:13:48.000000', NULL, 1),
(383458, 31892, 8981, '<td valign="top">Cute picture!  Unfortunatly I don''t think the main focus here is the handrail, which is the part meeting the challenge.</td>', 'Cute picture!  Unfortunatly I don''t think the main focus here is the handrail, which is the part meeting the challenge.', '2003-08-10 23:15:39.000000', NULL, 1),
(383459, 31994, 7810, '<td valign="top">cool shot</td>', 'cool shot', '2003-08-10 23:16:37.000000', NULL, 1),
(383460, 32244, 8981, '<td valign="top">Very nice.  I like the way you enhanced the "right angles" in this picture with the fence.</td>', 'Very nice.  I like the way you enhanced the "right angles" in this picture with the fence.', '2003-08-10 23:17:06.000000', NULL, 1),
(383462, 32030, 8981, '<td valign="top">This is really interesting.  I really like the colors and angels created here, but I''m having trouble finding a main focus.  My eyes are actually drawn to the parts that aren''t symetrical.</td>', 'This is really interesting.  I really like the colors and angels created here, but I''m having trouble finding a main focus.  My eyes are actually drawn to the parts that aren''t symetrical.', '2003-08-10 23:19:20.000000', NULL, 1),
(383464, 31968, 8981, '<td valign="top">I really like the colors in this!  I think it might have been a little more apropriate for this challenge if it had been taken from a different angle.</td>', 'I really like the colors in this!  I think it might have been a little more apropriate for this challenge if it had been taken from a different angle.', '2003-08-10 23:22:20.000000', NULL, 1),
(383465, 31480, 8981, '<td valign="top">Wow, I really like this!  The lines are great and I like the idea.  I think the image as a whole looks a little dull and pixlated though.  Besides that great job!</td>', 'Wow, I really like this!  The lines are great and I like the idea.  I think the image as a whole looks a little dull and pixlated though.  Besides that great job!', '2003-08-10 23:24:28.000000', NULL, 1),
(383468, 32175, 8981, '<td valign="top">This is a really neat picture.  I think it would have been good for the garden challenge as well.</td>', 'This is a really neat picture.  I think it would have been good for the garden challenge as well.', '2003-08-10 23:25:55.000000', NULL, 1),
(383470, 31669, 8981, '<td valign="top">Very nice!  This looks very sharp and crisp. I\''m immediatly drawn to the right angles in this photo.  Great job!</td>', 'Very nice!  This looks very sharp and crisp. I\''m immediatly drawn to the right angles in this photo.  Great job!', '2003-08-10 23:27:04.000000', NULL, 1),
(383472, 32148, 8981, '<td valign="top">Very nice image, but I''m having trouble finding the right angles here.  If it''s a play on the challenge I give you credit for the creativity.</td>', 'Very nice image, but I''m having trouble finding the right angles here.  If it''s a play on the challenge I give you credit for the creativity.', '2003-08-10 23:28:28.000000', NULL, 1),
(383491, 31864, 6870, '<td valign="top">Very nice eye for pattern here. The roundish shapes above sets off the angles nicely. The image seems a bit grainy, and I can''t see a reason for it here. But nice work.</td>', 'Very nice eye for pattern here. The roundish shapes above sets off the angles nicely. The image seems a bit grainy, and I can''t see a reason for it here. But nice work.', '2003-08-10 23:46:19.000000', NULL, 1),
(383493, 31543, 6870, '<td valign="top">Simple and clear communication. Interesting, too.</td>', 'Simple and clear communication. Interesting, too.', '2003-08-10 23:46:46.000000', NULL, 1),
(383494, 31615, 6870, '<td valign="top">The woman''s non-square shape sets off your angles nicely. Lighting seems a bit harsh. Wonderful composition and cropping.</td>', 'The woman''s non-square shape sets off your angles nicely. Lighting seems a bit harsh. Wonderful composition and cropping.', '2003-08-10 23:47:38.000000', NULL, 1),
(383496, 31650, 10263, '<td valign="top">I like this and the kids look like they are having fun with it too. Cute idea :)</td>', 'I like this and the kids look like they are having fun with it too. Cute idea :)', '2003-08-10 23:49:02.000000', NULL, 1),
