(384713, 32044, 9723, '<td valign="top">All that effort, and the shot needs to be straightened! Details, details.</td>', 'All that effort, and the shot needs to be straightened! Details, details.', '2003-08-11 20:30:56.000000', NULL, 1),
(384716, 32203, 9723, '<td valign="top">I really like this shot. Very colorful and contrasty. Highly visually stimulating.</td>', 'I really like this shot. Very colorful and contrasty. Highly visually stimulating.', '2003-08-11 20:33:15.000000', NULL, 1),
(384720, 31935, 9723, '<td valign="top">Ya see? A cloudy day, when so many folks would leave the camera at home, and you turned out this beautifully colorful shot full of saturation and contrast. Well done.</td>', 'Ya see? A cloudy day, when so many folks would leave the camera at home, and you turned out this beautifully colorful shot full of saturation and contrast. Well done.', '2003-08-11 20:40:23.000000', NULL, 1),
(384721, 32055, 9723, '<td valign="top">Nice idea, but it needs something to make it pop out of the frame. More lightness, more contrast.</td>', 'Nice idea, but it needs something to make it pop out of the frame. More lightness, more contrast.', '2003-08-11 20:43:02.000000', NULL, 1),
(384722, 32212, 9723, '<td valign="top">It might be a more powerful shot if you cropped out the portion of the wall with the light on it on the left. See what you think.</td>', 'It might be a more powerful shot if you cropped out the portion of the wall with the light on it on the left. See what you think.', '2003-08-11 20:45:48.000000', NULL, 1),
