(384746, 31913, 9723, '<td valign="top">What a nicely done photo. Super well composed. Focus and DOF are "right"on.</td>', 'What a nicely done photo. Super well composed. Focus and DOF are "right"on.', '2003-08-11 21:06:25.000000', NULL, 1),
(384769, 31615, 1368, '<td valign="top">its a very nice photo you got there mister Is this Mr. Iggy Popp</td>', 'its a very nice photo you got there mister Is this Mr. Iggy Popp', '2003-08-11 21:33:17.000000', NULL, 1),
(384781, 32193, 5925, '<td valign="top">Brilliant idea!  I really like this one.  I can''t find anything to critique in this shot at all.</td>', 'Brilliant idea!  I really like this one.  I can''t find anything to critique in this shot at all.', '2003-08-11 21:39:39.000000', NULL, 1),
