(385107, 32228, 7190, '<td valign="top">I would have liked to seen the top of the building but as I refer to it you caught the sweet light. nice</td>', 'I would have liked to seen the top of the building but as I refer to it you caught the sweet light. nice', '2003-08-12 10:25:41.000000', NULL, 1),
