INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(385147, 31882, 10332, '<td valign="top">I love the natural and manmade combination</td>', 'I love the natural and manmade combination', '2003-08-12 11:19:16.000000', NULL, 1),
(385148, 31749, 10441, '<td valign="top">Great idea for the challenge.</td>', 'Great idea for the challenge.', '2003-08-12 11:19:31.000000', NULL, 1),
(385149, 31661, 10441, '<td valign="top">Nice composition and use of lighting.</td>', 'Nice composition and use of lighting.', '2003-08-12 11:20:00.000000', NULL, 1),
(385150, 31315, 10441, '<td valign="top">Cool idea for the challenge.</td>', 'Cool idea for the challenge.', '2003-08-12 11:20:41.000000', NULL, 1),
(385151, 31933, 10785, '<td valign="top">This is similar to what I tried to do for this contest, though your photo far exceeded mine. You really took a good shot here. Your shot is very crisp, has good contrast and the slice of color adds to the composition. I also like the way it was framed. You either cropped it well, or framed it up so the lines in the triangle were evenly spaced throughout the width of the photo. An excellent Job!</td>', 'This is similar to what I tried to do for this contest, though your photo far exceeded mine. You really took a good shot here. Your shot is very crisp, has good contrast and the slice of color adds to the composition. I also like the way it was framed. You either cropped it well, or framed it up so the lines in the triangle were evenly spaced throughout the width of the photo. An excellent Job!', '2003-08-12 11:23:06.000000', NULL, 1),
(385152, 31265, 10785, '<td valign="top">The way you got the light to shine in between the hands was incredible!</td>', 'The way you got the light to shine in between the hands was incredible!', '2003-08-12 11:24:35.000000', NULL, 1),
(385157, 31951, 9083, '<td valign="top">great colours</td>', 'great colours', '2003-08-12 11:41:47.000000', NULL, 1),
(385158, 31293, 10516, '<td valign="top">Sorry but I did not see how this met the challenge... Good picture overall and I would have moved  the object in the upper left out of the picture.</td>', 'Sorry but I did not see how this met the challenge... Good picture overall and I would have moved  the object in the upper left out of the picture.', '2003-08-12 11:41:53.000000', NULL, 1),
(385160, 31882, 9083, '<td valign="top">Lovely photograph nicely framed</td>', 'Lovely photograph nicely framed', '2003-08-12 11:44:51.000000', NULL, 1),
(385164, 32203, 9083, '<td valign="top">Absolute winner, great angle great composition, great lighting, love it</td>', 'Absolute winner, great angle great composition, great lighting, love it', '2003-08-12 11:46:03.000000', NULL, 1),
(385166, 32204, 9083, '<td valign="top">Brilliant shot, well framed , good lighting</td>', 'Brilliant shot, well framed , good lighting', '2003-08-12 11:46:54.000000', NULL, 1),
(385172, 31666, 4380, '<td valign="top">quite grainy but the concept is excellent...8</td>', 'quite grainy but the concept is excellent...8', '2003-08-12 11:57:43.000000', NULL, 1),
(385174, 32188, 4380, '<td valign="top">the concept is simple but its very good...7</td>', 'the concept is simple but its very good...7', '2003-08-12 11:59:03.000000', NULL, 1),
(385175, 31997, 11135, '<td valign="top">I love this picture. It''s a 10 in my book. how did you get such a black background?</td>', 'I love this picture. It''s a 10 in my book. how did you get such a black background?', '2003-08-12 11:59:56.000000', NULL, 1),
(385176, 31292, 4380, '<td valign="top">i like the colours, i like the patterns  and excellent composition...good luck...here''s my 10</td>', 'i like the colours, i like the patterns  and excellent composition...good luck...here''s my 10', '2003-08-12 12:00:23.000000', NULL, 1),
(385178, 32228, 11135, '<td valign="top">I love the shadows in this picture as well as the position that the building is. I''m not sure if you waited for the sun to get lower or just got there at a good time, but either way, great shot.</td>', 'I love the shadows in this picture as well as the position that the building is. I''m not sure if you waited for the sun to get lower or just got there at a good time, but either way, great shot.', '2003-08-12 12:01:40.000000', NULL, 1),
(385181, 32174, 4380, '<td valign="top">yeah...excellent...awesome image..i like the sparkling...how about using a star filter? anyway...give you 9...it should be 10 if you use the star filter for the effect. CONGRATS!!!</td>', 'yeah...excellent...awesome image..i like the sparkling...how about using a star filter? anyway...give you 9...it should be 10 if you use the star filter for the effect. CONGRATS!!!', '2003-08-12 12:02:26.000000', NULL, 1),
(385182, 32251, 4380, '<td valign="top">i like the simplicity of the image...7</td>', 'i like the simplicity of the image...7', '2003-08-12 12:03:11.000000', NULL, 1),
(385183, 32037, 4380, '<td valign="top">very classic,  the composition is just awesome...great image...congrats...8</td>', 'very classic,  the composition is just awesome...great image...congrats...8', '2003-08-12 12:04:03.000000', NULL, 1),
(385184, 32238, 11135, '<td valign="top">I REALLY like the content, however, it seems dirty to me. The light is awesome, but there are spots in the lower right as well as on the table. I''m not sure what is causing them and suspect that they were actually on the wall. Also, the light seems just a little bit too washed out. Great shot though. I like it.</td>', 'I REALLY like the content, however, it seems dirty to me. The light is awesome, but there are spots in the lower right as well as on the table. I''m not sure what is causing them and suspect that they were actually on the wall. Also, the light seems just a little bit too washed out. Great shot though. I like it.', '2003-08-12 12:05:04.000000', NULL, 1),
(385185, 31568, 4380, '<td valign="top">its very light..i really go for simplicity...7</td>', 'its very light..i really go for simplicity...7', '2003-08-12 12:05:22.000000', NULL, 1),
(385186, 31784, 11135, '<td valign="top">I love the color, the angle, the focus.... it''s all just great. Nice job.</td>', 'I love the color, the angle, the focus.... it''s all just great. Nice job.', '2003-08-12 12:06:02.000000', NULL, 1),
(385187, 31882, 4380, '<td valign="top">great eye, fantastic lighting, excellent angle...what can i say but almost perfect..got 9...congrats.</td>', 'great eye, fantastic lighting, excellent angle...what can i say but almost perfect..got 9...congrats.', '2003-08-12 12:06:37.000000', NULL, 1),
(385188, 32044, 11135, '<td valign="top">Perfect contrast... VERY nice b/w picture.</td>', 'Perfect contrast... VERY nice b/w picture.', '2003-08-12 12:06:53.000000', NULL, 1),
(385189, 31881, 4380, '<td valign="top">you got humour, naughty pix...is that red eye? i like the idea...6</td>', 'you got humour, naughty pix...is that red eye? i like the idea...6', '2003-08-12 12:07:50.000000', NULL, 1),
(385190, 32156, 11135, '<td valign="top">I love the photojournalistic aspect here. Nice timing, and great shot.</td>', 'I love the photojournalistic aspect here. Nice timing, and great shot.', '2003-08-12 12:07:54.000000', NULL, 1),
(385191, 32145, 11135, '<td valign="top">Behold, the power of cheese =) Nice picture!</td>', 'Behold, the power of cheese =) Nice picture!', '2003-08-12 12:08:21.000000', NULL, 1),
(385192, 31615, 11135, '<td valign="top">I like the frame created by the wall. Very nice.</td>', 'I like the frame created by the wall. Very nice.', '2003-08-12 12:09:08.000000', NULL, 1),
(385199, 32080, 11135, '<td valign="top">I like what you were going for here, although, I think that the end result ended up being pretty busy. I''m not sure if getting lower under the windows would have helped spread the picture out some or not, but this is one of those pictures that I look at and say "Nice vision, but it didn''t reach it''s potential" Perhaps a narrower depth of field. I''m not sure, but I like what you saw here.</td>', 'I like what you were going for here, although, I think that the end result ended up being pretty busy. I''m not sure if getting lower under the windows would have helped spread the picture out some or not, but this is one of those pictures that I look at and say "Nice vision, but it didn''t reach it''s potential" Perhaps a narrower depth of field. I''m not sure, but I like what you saw here.', '2003-08-12 12:13:51.000000', NULL, 1),
(385205, 32226, 11135, '<td valign="top">Nice picture of the flower, but your hands become very distracting...</td>', 'Nice picture of the flower, but your hands become very distracting...', '2003-08-12 12:17:16.000000', NULL, 1),
(385211, 32243, 11135, '<td valign="top">Nice, but for some reason, it seems a little pixelized (sorry if I didn''t spell that correctly =) Did you crop this picture?</td>', 'Nice, but for some reason, it seems a little pixelized (sorry if I didn''t spell that correctly =) Did you crop this picture?', '2003-08-12 12:20:07.000000', NULL, 1),
(385212, 31653, 11135, '<td valign="top">Very busy! It''s hard for my eyes to find anything to latch onto. Perhaps an angle that would have been more from the right side would have helped to ease that up some.</td>', 'Very busy! It''s hard for my eyes to find anything to latch onto. Perhaps an angle that would have been more from the right side would have helped to ease that up some.', '2003-08-12 12:21:30.000000', NULL, 1),
(385224, 32065, 2567, '<td valign="top">Nothing seems in focus here right from the fence in front to the sky meeting the mountains.  Even the building, the main subject,  is not in focus.  This might have been a good shot had it been taken closer to the building.</td>', 'Nothing seems in focus here right from the fence in front to the sky meeting the mountains.  Even the building, the main subject,  is not in focus.  This might have been a good shot had it been taken closer to the building.', '2003-08-12 12:52:09.000000', NULL, 1),
